$(document).ready(function() {
    $('.actionBtn').on('click',function () {
        var action = $(this).data('action');
        $("#actionForm").find('input[name="action"]').val(action);
        $('#actionFormModalLabel').html(action);
        if (action == 'paid') {
            $('#paymentinfoLabel').html("payment code");
        } else {
            $('#paymentinfoLabel').html(action + ' information');
        }
        $('#actionFormModal').modal('show');
    });
    $('.btn-action-submit').on('click',function () {
        $("#actionForm").submit();
    });

    $('.js-material-input').select2({
        theme: "bootstrap-5",
        allowClear: true,
        tags: true,
        placeholder: "Materials",
        ajax: {
            url: '/ajax/getMaterialInput.json',
            dataType: 'json',
            quietMillis: 50,
            data: function (params) {
                console.log(this);
                var $element = $(this);
                var materialid = $element.data('materialid');
                var quantity = $element.data('quantity');
                var d = {
                    materialid: materialid,
                    ordernumber: $('#load-ordernumber').html(),
                    quantity: 0,
                    searchTerm: params.term,
                    page: params.page ? params.page : 1,
                    maxPageItems: 10
                };
                return d;
            },
            processResults: function (data) {
                return {
                    results: $.map(data, function (item) {
                        item.text ="Số lô: " + item.slotno + " - Ngày nhập: " + item.inputtime;
                        item.id =  item.materialinputid;
                        return item;
                    })
                };
            },
            dropdownCssClass: "bigdrop",
            containerCssClass: "form-select",
            containerCss: "form-select",
        },
        minimumResultsForSearch: Infinity,
    }).on("change", function (e) {
        var data = $(this).select2('data')[0];
        var keycuspro = data.keycuspro
        var qtyinstock = data.qtyinstock;
        var expdate = data.expdate;
        var mfgdate = data.mfgdate;

        var tr = $(this).closest('tr');
        $($(tr).find('.qtyinstock')[0]).html(qtyinstock + "/" + data.quantity);
        $($(tr).find('.expdate')[0]).html(expdate);
        $($(tr).find('.mfgdate')[0]).html(mfgdate);
        $($(tr).find('input[name="quantity"]')[0]).attr("max", qtyinstock);
    });

    function validForm() {
        return true;
    }

    function validMaterialOutputData(data) {
        var result = true;
        var list = data.list;
        var totalQuantity = 0;
        for(var i = 0; i < list.length ; i++){
            if (list[i].quantity > list[i].qtyinstock) {
                result = false;
                window.alert("Quantity in stock not available");
            }
            totalQuantity+=Number(list[i].quantity);
        }
        var quantity = Number($('#item_quantity').html());
        if (totalQuantity != quantity) {
            result = false;
            window.alert("Quantity error");
        }
        return result;
    }

    function generateMaterialOutputData() {
        var listQuantity = $('.js-material-input-quantity');
        var listSlotno= $('.js-material-input');
        var index = 0;
        var mapData = {};
        var totalQuantity = 0;
        listSlotno.each(function () {
            var slotnoData =$(this).select2('data');
            if(slotnoData != null && slotnoData[0].materialinputid != undefined){
                for (var i = 0; i < slotnoData.length ; i++) {
                    var quantity = $(listQuantity[index]).val() || 0;
                    quantity = Number(quantity);
                    if (quantity > 0) {
                        var item = slotnoData[i];
                        totalQuantity += quantity;
                        var obj = {
                            ordernumber: $('#load-ordernumber').html(),
                            quantity: quantity,
                            materialinput: {
                                materialinputid: item.materialinputid
                            },
                            qtyinstock: item.qtyinstock
                        }
                        if (mapData[item.materialinputid] != undefined) {
                            obj.quantity = obj.quantity + mapData[item.materialinputid].quantity;
                        }
                        mapData[item.materialinputid] = obj;
                    }
                }
            }
            index++;
        });

        var list = [];
        for (var i = 0; i < Object.keys(mapData).length; i++) {
            list.push(mapData[Object.keys(mapData)[i]]);
        }
        return {
            list: list,
            ordernumber: $('#load-ordernumber').html()
        };
    }

    $('.js-submit-material-output').on('click', function () {
        if (validForm()) {
            var formData = generateMaterialOutputData();
            if (validMaterialOutputData(formData)){
                $.ajax({
                    url: '/ajax/saveMaterialOutput.json',
                    type: 'POST',
                    data: JSON.stringify(formData),
                    contentType: "application/json",
                    dataType: 'json',
                    success: function(result) {
                        window.location.reload();
                    }
                });
            }
        }
    });

    $('.js-action-edit').on('click', function () {
        $(this).addClass('d-none');
        $('#editMaterialOutputForm').removeClass('d-none');
    });
});
